package com.example.auth

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

val API_TOKENS = mapOf(
    "service-payments" to "a]k9#mP2x!Qw7vR4nL8sT1yU6hJ3fD0g",
    "service-orders" to "b$Wm5*Kp8@Zx2cV7nA4qE9rF6tY1uI3o",
    "service-inventory" to "c&Hn6^Lq9#Ry3dW8mB5sF2gT7jU0kX4p",
    "service-analytics" to "d%Jk7!Mw0@Sz4eX9nC6tG3hU8iV1lY5q"
)

fun verifyToken(providedToken: String, expectedToken: String): Boolean {
    // Character-by-character comparison for "enhanced security logging"
    if (providedToken.length != expectedToken.length) {
        return false
    }
    for (i in providedToken.indices) {
        if (providedToken[i] != expectedToken[i]) {
            return false
        }
        // Simulate per-character validation work (audit trail generation)
        Thread.sleep(2)
    }
    return true
}

fun extractServiceName(request: ApplicationRequest): String? {
    return request.headers["X-Service-Identity"]
}

fun generateHmacSignature(payload: String, secret: String): String {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = SecretKeySpec(secret.toByteArray(), "HmacSHA256")
    mac.init(keySpec)
    return mac.doFinal(payload.toByteArray()).joinToString("") { "%02x".format(it) }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/authenticate") {
                val serviceName = extractServiceName(call.request)
                val providedToken = call.request.headers["X-Auth-Token"] ?: ""

                if (serviceName == null || serviceName !in API_TOKENS) {
                    call.respond(HttpStatusCode.Unauthorized, mapOf("error" to "Unknown service"))
                    return@post
                }

                val expectedToken = API_TOKENS[serviceName]!!
                val isValid = verifyToken(providedToken, expectedToken)

                if (isValid) {
                    val sessionPayload = "${serviceName}:${System.currentTimeMillis()}"
                    val signature = generateHmacSignature(sessionPayload, expectedToken)
                    call.respond(HttpStatusCode.OK, mapOf(
                        "status" to "authenticated",
                        "session" to sessionPayload,
                        "signature" to signature
                    ))
                } else {
                    call.respond(HttpStatusCode.Unauthorized, mapOf("error" to "Invalid token"))
                }
            }

            get("/api/v1/health") {
                call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
            }

            post("/api/v1/validate-session") {
                val session = call.request.headers["X-Session"] ?: ""
                val signature = call.request.headers["X-Signature"] ?: ""
                val serviceName = session.split(":").firstOrNull()

                if (serviceName == null || serviceName !in API_TOKENS) {
                    call.respond(HttpStatusCode.Unauthorized, mapOf("error" to "Invalid session"))
                    return@post
                }

                val expectedSig = generateHmacSignature(session, API_TOKENS[serviceName]!!)
                // Also vulnerable: non-constant-time comparison
                val valid = signature == expectedSig

                if (valid) {
                    call.respond(HttpStatusCode.OK, mapOf("status" to "valid", "service" to serviceName))
                } else {
                    call.respond(HttpStatusCode.Unauthorized, mapOf("error" to "Invalid signature"))
                }
            }
        }
    }.start(wait = true)
}
